def A(title, pages, central, adjacent, explain, examples, relations, text, daily, intro, app, apps=()):
    """text = (صاحب النص، فكرته، الإشكال المحوري، الأطروحة والموقف)"""
    author, gist, problem, thesis = text
    board = [
        {"h": "المفهوم المركزي", "lines": [f"{central[0]}: {central[1]}"]},
        {"h": "المفاهيم المجاورة", "lines": [], "table": [["المفهوم", "تعريفه"]] + [list(a) for a in adjacent]},
        {"h": "شرح وتحليل", "lines": explain},
        {"h": "التمثيل والعلاقات", "lines": ["العلاقات: " + " ؛ ".join(relations)], "table": [["المفهوم", "مثال"]] + [list(e) for e in examples]},
        {"h": f"النص التطبيقي: {author}", "lines": [gist, "الإشكال المحوري: " + problem, thesis]},
        {"h": "مشكل من المعيش اليومي", "lines": [daily]},
    ]
    return {"title": title, "match": [title], "pages": pages,
            "objectives": [f"أن يحدد الطالب مفهوم «{central[0]}» ودلالاته.",
                           "أن يميز المفاهيم المجاورة ويحدد العلاقات بينها: " + "، ".join(a[0] for a in adjacent) + ".",
                           "أن يشتغل على نص فلسفي: أسئلة الفقرات، الإشكال المحوري، الأطروحة والموقف منها.",
                           "أن يقترح حلا لمشكل من المعيش اليومي مرتبط بالمفهوم."],
            "intro": intro,
            "summary": f"{central[0]}: {central[1]} " + " ".join(explain) + " المفاهيم المجاورة: " + "؛ ".join(f"{a[0]}: {a[1]}" for a in adjacent) + ".",
            "points": [f"{central[0]}: {central[1]}"] + [f"{a[0]}: {a[1]}" for a in adjacent] + [f"نص {author}: {problem}"],
            "application": {"q": app[0], "a": app[1]},
            "applications": [{"q": q, "a": a} for q, a in apps], "board": board}

